import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(address x) internal {
        bool reverted;
        try c.SetLogFile(x) { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted);
    }

    function testFuzz_run(address x) public {
        vm.assume(x.code.length == 0 && uint160(x) > 0xffff && x != address(this) && x != address(c) && x != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && x != 0x000000000000000000636F6e736F6c652e6c6f67 && x != 0x4e59b44847b379578588920cA78FbF26c0B4956C && x != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(x);
    }

    receive() external payable {}
}
